#!/bin/sh
# Regenerate every campaign summary that a committed script rebuilds from the committed per-run JSONs, compare each
# regenerated file with the committed one, then run tools/check_results_index.py. No SPICE is run.
#
# Usage:  sh tools/reproduce_summaries.sh
#
# The scripts write their summaries in place (results/<campaign>/summary/...). Run this in a clean clone: afterwards
# `git status` shows any file that came out different; `git checkout -- results docs` restores the committed versions.
# Summaries written by simulation scripts (stress audits, gate/warm-start runs, B5 short runs, the calibration
# design constants) and by the CPU-only training searches (A0 ceilings, A1 training jobs, option-d timing screen,
# A4 re-run) are not rebuilt here; REPRODUCE.md says how to re-run them.
# Six summary steps read simulated waveforms, netlists or Monte Carlo draw files, which are not included in this
# repository (phase3_c2slope.py, failure_devices.py, calib_mismatch.py, check_pairing.py, b3_summary.py,
# b4_mu_explain.py). They run only after those files have been regenerated by re-running the campaign phases
# (REPRODUCE.md §6); this script does not run them.
# Python: numpy for most steps; the weights_schemeA steps also import scipy, scikit-learn, highspy and numba
# (pip install -r results/weights_schemeA/requirements.txt).
set -u
R=$(cd "$(dirname "$0")/.." && pwd)
export PYTHONDONTWRITEBYTECODE=1
LOG=$(mktemp -d)
sh "$R/tools/setup_layout.sh" > "$LOG/layout.txt" 2>&1 || { cat "$LOG/layout.txt"; exit 2; }
FAILED=0; NSTEP=0
T0=$(date +%s)

step() {  # step <campaign scripts dir> <label> <command...>
  d="$1"; label="$2"; shift 2
  NSTEP=$((NSTEP + 1))
  s=$(date +%s)
  if (cd "$R/results/$d" && "$@") > "$LOG/$NSTEP.out" 2> "$LOG/$NSTEP.err"; then st=ok; else st=FAILED; FAILED=$((FAILED + 1)); fi
  printf '  %-6s %4ss  %-28s %s\n' "$st" "$(( $(date +%s) - s ))" "$(dirname "$d")" "$label"
  [ "$st" = ok ] || tail -3 "$LOG/$NSTEP.err" | sed 's/^/           /'
}

echo "== regenerating summaries from per-run JSONs"
F=fitc10_campaign/scripts
step $F "analytic.py (no SPICE; schemeA model)"            python3 analytic.py
step $F "summarize.py phase1 (Variant 1)"                  env FC10_VARIANT=1 python3 summarize.py phase1
step $F "summarize.py chain (Variant 1)"                   env FC10_VARIANT=1 python3 summarize.py chain
step $F "summarize.py phase3A (Variant 1, partial)"        env FC10_VARIANT=1 python3 summarize.py phase3A
step $F "summarize.py all (Variant 3)"                     env FC10_VARIANT=3 python3 summarize.py all
step $F "compare_variants.py"                              python3 compare_variants.py
WS=weights_schemeA/scripts
step $WS "splits.py"                                       python3 splits.py
step $WS "calib_fit.py"                                    python3 calib_fit.py
step $WS "calib_retrim.py"                                 python3 calib_retrim.py
step $WS "calib_colsum.py"                                 python3 calib_colsum.py
step $WS "cv_eval.py (surrogate, A1 jobs)"                 python3 cv_eval.py
step $WS "select_spice.py summary"                         python3 select_spice.py summary cand_a cand_b cand_c
step $WS "eval_test.py summary FINAL_frozen"               python3 eval_test.py summary FINAL_frozen
step $WS "robustness.py summary FINAL_frozen"              python3 robustness.py summary FINAL_frozen
step $WS "report_tables.py"                                python3 report_tables.py
EH=energy_host/scripts
step $EH "b1_summary.py"                                   python3 b1_summary.py
step $EH "b2_summary.py"                                   python3 b2_summary.py
step $EH "b4_summary.py"                                   python3 b4_summary.py
step $EH "b5_summary.py"                                   python3 b5_summary.py
step $EH "report_tables.py (rewrites REPORT.md tables)"    python3 report_tables.py
step host_v2/scripts "summ_phases.py all"                  python3 summ_phases.py all
step host_v21/scripts "summ21.py all"                      python3 summ21.py all
step fitc10_campaign/scripts "tools/gen_nominal_netlist.py --check" python3 "$R/tools/gen_nominal_netlist.py" --check

echo "== comparing regenerated files with the committed ones"
(cd "$R" && python3 - <<'PY'
import json, subprocess, sys
st = subprocess.run(["git", "status", "--porcelain", "--", "results", "docs"], capture_output=True, text=True).stdout.splitlines()
changed = [l[3:] for l in st if l[:2].strip()]
if not changed:
    print("  all regenerated files are byte-identical to the committed ones")
bad = 0
for f in changed:
    if f.endswith(".json"):
        try:
            old = json.loads(subprocess.run(["git", "show", f"HEAD:{f}"], capture_output=True, text=True, check=True).stdout)
            same = old == json.load(open(f))
        except Exception:
            same = False
        print(f"  {'same content, different formatting/key order' if same else 'DIFFERS'}: {f}")
        bad += not same
    else:
        print(f"  DIFFERS: {f}")
        bad += 1
sys.exit(1 if bad else 0)
PY
) || FAILED=$((FAILED + 1))

echo "== tools/check_results_index.py"
if python3 "$R/tools/check_results_index.py" > "$LOG/check.txt" 2>&1; then tail -1 "$LOG/check.txt"
else grep -v "^  OK" "$LOG/check.txt"; FAILED=$((FAILED + 1)); fi

echo "reproduce_summaries.sh: $NSTEP steps, $FAILED problem(s), $(( $(date +%s) - T0 )) s (logs in $LOG)"
[ $FAILED = 0 ]
